            for component_id, solver in SOLVERS.items()}

from itertools import combinations, product
import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked or len(mandatory) > k:
            return {"error": "impossible"}

        options = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue

            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            feasible = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    feasible = False
                    break
            if not feasible:
                continue

            value = sum(job["value"] for job in subset)
            selected = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (selected > best_ids if tie == "largest" else selected < best_ids))):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _ledger_solver(data):
    def rounded(numerator, denominator, mode):
        quotient, remainder = divmod(numerator, denominator)
        if mode == "half_up" and 2 * remainder >= denominator:
            quotient += 1
        return quotient

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    options = {}
    for name in names:
        rows = packages[name]
        versions = sorted(row["version"] for row in rows)
        allowed = [v for v in versions
                   if v not in blocked.get(name, [])
                   and (name not in pins or pins[name] == v)]
        options[name] = [None] + allowed

    best_vector = None
    best_versions = None
    for values in product(*(options[name] for name in names)):
        chosen = dict(zip(names, values))
        if any(chosen.get(name) is None or
               not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        rows_by_name = {
            name: next((row for row in packages[name]
                        if row["version"] == chosen[name]), None)
            for name in names if chosen[name] is not None
        }
        edges = {}
        valid = True
        for name, row in rows_by_name.items():
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = chosen.get(target)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                deps.append(target)
            edges[name] = deps
            if not valid:
                break
        if not valid:
            continue

        # Every installed package must be in the active closure of the roots.
        reached = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reached:
                continue
            reached.add(name)
            pending.extend(edges.get(name, []))
        installed = {name for name, version in chosen.items() if version is not None}
        if reached != installed:
            continue

        state, finished = set(), set()
        def visit(name):
            if name in state:
                return False
            if name in finished:
                return True
            state.add(name)
            if any(not visit(dep) for dep in edges.get(name, [])):
                return False
            state.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in installed):
            continue

        vector = tuple(chosen[name] if chosen[name] is not None else -1
                       for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_versions = {name: chosen[name] for name in names
                             if chosen[name] is not None}

    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _route_solver(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            for duration, next_remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask,
                                           next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _interval_solver(1, "largest"),
    "component_02": _interval_solver(2, "largest"),
    "component_03": _interval_solver(1, "smallest"),
    "component_04": _interval_solver(2, "smallest"),
    "component_05": _interval_solver(1, "largest"),
    "component_06": _ledger_solver,
    "component_07": _dependency_solver,
    "component_08": _route_solver,
}
